  "inlineSchema": "// ============================================================================\n// Budget App — Prisma Schema\n// ============================================================================\n// Design notes:\n// - Users can configure their own payday(s) (e.g. 15th & 30th) via PaySchedule.\n// - Each concrete cycle (\"July 30\", \"August 15\") is a PayPeriod row, generated\n//   from the PaySchedule (either by a cron job / server action or on demand).\n// - Recurring line items (Transportation Allowance, Grocery, etc.) live as\n//   BudgetItemTemplate so they don't need to be retyped every period; each\n//   PayPeriod gets its own BudgetItem rows cloned from the active templates,\n//   which can then be edited/overridden per period without touching the template.\n// - BudgetCategory captures the color-coded groupings seen in the sheet\n//   (black/starred essentials, green \"to collect\" income, purple debts).\n// - The dropdown in column D maps to BudgetItem.status.\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ----------------------------------------------------------------------------\n// Enums\n// ----------------------------------------------------------------------------\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum PayFrequency {\n  MONTHLY // one payday per month\n  SEMI_MONTHLY // two fixed calendar days per month (e.g. 15th & 30th) — matches your sheet\n  BIWEEKLY // every 14 days\n  WEEKLY\n  CUSTOM\n}\n\nenum ItemType {\n  EXPENSE // black/starred rows: Transportation Allowance, Grocery, etc.\n  DEBT // purple rows: BPI Credit Card, SPayLater, etc.\n  INCOME // green rows: Collect 1K From Accenture\n  SAVINGS // e.g. \"Savings\" row\n}\n\nenum ItemStatus {\n  PENDING\n  PAID\n  PARTIAL\n  SKIPPED\n  OVERDUE\n}\n\n// ----------------------------------------------------------------------------\n// Users & Auth\n// ----------------------------------------------------------------------------\n\nmodel User {\n  id           String  @id @default(cuid())\n  email        String  @unique\n  passwordHash String\n  name         String?\n  role         Role    @default(USER)\n  currency     String  @default(\"PHP\")\n  isActive     Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  paySchedule   PaySchedule?\n  payPeriods    PayPeriod[]\n  categories    BudgetCategory[]\n  itemTemplates BudgetItemTemplate[]\n\n  @@index([role])\n}\n\n// ----------------------------------------------------------------------------\n// Payday configuration\n// ----------------------------------------------------------------------------\n\nmodel PaySchedule {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  frequency PayFrequency @default(SEMI_MONTHLY)\n\n  // Calendar days of the month payday falls on, e.g. [15, 30].\n  // For months with fewer days (e.g. no 30th in Feb), the generator\n  // should clamp to the last day of the month.\n  payDays Int[] @default([15, 30])\n\n  // Used only when frequency = WEEKLY / BIWEEKLY, 0 = Sunday ... 6 = Saturday\n  anchorWeekday Int?\n\n  // Used only when frequency = BIWEEKLY / CUSTOM to compute the next date\n  anchorDate DateTime?\n\n  timezone String @default(\"Asia/Manila\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------------------------------\n// Categories (color-coded groupings)\n// ----------------------------------------------------------------------------\n\nmodel BudgetCategory {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name      String // e.g. \"Necessities\", \"Bills\", \"Debts & Credit\", \"Income\"\n  color     String @default(\"#000000\") // hex, drives the row color in UI\n  sortOrder Int    @default(0)\n\n  templates BudgetItemTemplate[]\n  items     BudgetItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name])\n  @@index([userId])\n}\n\n// ----------------------------------------------------------------------------\n// Recurring item templates (the \"starred\" rows that repeat every period)\n// ----------------------------------------------------------------------------\n\nmodel BudgetItemTemplate {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  categoryId String?\n  category   BudgetCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  name          String // \"Transportation Allowance\", \"Cat necessities\", etc.\n  type          ItemType @default(EXPENSE)\n  defaultAmount Decimal  @db.Decimal(12, 2)\n  isStarred     Boolean  @default(true)\n  isActive      Boolean  @default(true) // stop generating this item without deleting history\n  sortOrder     Int      @default(0)\n  notes         String?\n\n  items BudgetItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name])\n  @@index([userId, isActive])\n}\n\n// ----------------------------------------------------------------------------\n// Concrete pay periods (\"July 30\", \"August 15\", ...)\n// ----------------------------------------------------------------------------\n\nmodel PayPeriod {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  label       String // e.g. \"July 30\" — denormalized for display, derived from payDate\n  payDate     DateTime // the actual payday date this period is anchored to\n  periodStart DateTime? // optional: start of the covered date range\n  periodEnd   DateTime? // optional: end of the covered date range\n\n  // Denormalized totals kept in sync via app logic / triggers for fast reads,\n  // but always re-derivable from BudgetItem rows.\n  totalAllocated Decimal @default(0) @db.Decimal(12, 2) // sum of EXPENSE/DEBT/SAVINGS (\"Total\" row)\n  totalIncome    Decimal @default(0) @db.Decimal(12, 2) // \"Total Income\"\n  totalBalance   Decimal @default(0) @db.Decimal(12, 2) // \"Total Balance\" = totalIncome - totalAllocated\n\n  items BudgetItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, payDate])\n  @@index([userId, payDate])\n}\n\n// ----------------------------------------------------------------------------\n// Line items within a specific pay period (one row in the sheet)\n// ----------------------------------------------------------------------------\n\nmodel BudgetItem {\n  id          String    @id @default(cuid())\n  payPeriodId String\n  payPeriod   PayPeriod @relation(fields: [payPeriodId], references: [id], onDelete: Cascade)\n\n  templateId String?\n  template   BudgetItemTemplate? @relation(fields: [templateId], references: [id], onDelete: SetNull)\n\n  categoryId String?\n  category   BudgetCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  name      String // copied from template at creation time, editable per period\n  type      ItemType   @default(EXPENSE)\n  amount    Decimal    @db.Decimal(12, 2)\n  isStarred Boolean    @default(false)\n  status    ItemStatus @default(PENDING) // powers the column D dropdown\n  sortOrder Int        @default(0)\n  notes     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([payPeriodId])\n  @@index([payPeriodId, type])\n}\n\n// ----------------------------------------------------------------------------\n// Seeder Tracking\n// ----------------------------------------------------------------------------\n\nmodel SeedHistory {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n}\n",
